    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            if x: counts[x] = counts.get(x, 0) + 1
    if len(counts) < 2:
        return [row[:] for row in grid]
    # Fill the two-cell exterior moat with the unique sparse accent color;
    # preserve the object's interior and frame exactly.
    accent = min(counts, key=counts.get)
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    out = [row[:] for row in grid]
    for r in range(max(0,r0-2), min(h,r1+3)):
        for c in range(max(0,c0-2), min(w,c1+3)):
            if grid[r][c] == 0: out[r][c] = accent
    return out
